let manifest, corpus, review, release, model, journey, transition=false, view='atlas', grade=7, student='Eva';
const $=s=>document.querySelector(s), node=id=>model.nodes.find(n=>n.id===id);
const standardId='wc:standard:ny-7-rp-2';
const sourceUrl='https://www.nysed.gov/sites/default/files/programs/curriculum-instruction/nys-math-standards-grade-7-crosswalk.pdf';
const titles={atlas:['What is New York asking students to learn?','Explore one traced Grade 7 mathematics standard. The full K–12 atlas is under construction; this checkpoint shows exactly what has been established.'],curriculum:['Curriculum','Follow the state’s familiar path from grade and subject to a standard and its parsed expectations.'],journey:['A capability through time','Developmental links require source review. This first slice establishes an endpoint, not a fabricated K–12 chain.'],crossroads:['Where subjects meet','Cross-disciplinary equivalences will appear here once they have evidence and review. None are asserted in this release.'],wildcats:['Follow the Wildcats','Matthew and Eva are fictional reference students. They have the same canonical expectations and no demonstrated-mastery data.'],workbench:['Inside the workbench','Coverage is a set of separate questions. Source identification, parsing, normalization, relationships, validation, and review do not advance together.'],findings:['Findings and open questions','Findings must be computed from the ontology and linked to their evidence. The first slice has no published discovery yet.'],log:['Lab Log','The public history of what entered the model, what was learned, and what remains open.']};
function sourceLink(source,page){return `https://github.com/GarageThermonuclearLaboratories/Minerva/blob/${release.research_commit||'main'}/${source.archive_path}#page=${page}`;}
function evidencePage(n){
const folder={'src:nysed:math-full':'math-full','src:nysed:ela-full':'ela-full'}[n.source_id];
return folder?`evidence/${folder}/page-${n.pdf_page}.png`:sourceLink(manifest.sources.find(s=>s.id===n.source_id),n.pdf_page);
}
function showReceipt(id){
const n=node(id);if(!n)return;
const original=n.original_text?n:(n.derived_from?node(n.derived_from):null);
const src=manifest.sources.find(x=>x.id===n.source_id);
const edges=model.edges.filter(e=>e.from===id||e.to===id);
const annotations=(original?.source_annotations||[]);
const children=model.nodes.filter(x=>x.type==='Expectation'&&x.derived_from===n.id);
const quote=original?.original_text||n.label;
$('#receipt-body').innerHTML=`<h2>${esc(n.label)}</h2><span class="tag ${n.status.toLowerCase()}">${esc(n.status)}</span>
<h3>${original?'SOURCE WORDING':'SOURCE STRUCTURE'}</h3><blockquote>${esc(quote)}</blockquote>
<p><a href="${esc(evidencePage(n))}" target="_blank" rel="noopener">View the source page</a> · <a href="${sourceLink(src,n.pdf_page)}" target="_blank" rel="noopener">Archived PDF · page ${n.pdf_page}</a></p>
<h3>PROJECT INTERPRETATION</h3><p>${esc(n.parsing_rationale||'Records the wording or placement in this source edition. No student mastery is demonstrated.')}</p>
${n.action?`<dl><dt>Action</dt><dd>${esc(n.action)}</dd><dt>Object</dt><dd>${esc(n.object)}</dd><dt>Qualifiers</dt><dd>${n.qualifiers.map(esc).join('; ')||'None beyond the source wording'}</dd></dl>`:''}
${annotations.map(a=>`<h3>${esc(a.kind)}</h3><blockquote>${esc(a.original_text)}</blockquote><p>${esc(a.interpretation)}</p>${a.example_summary?`<p>Example summary: ${esc(a.example_summary)}</p>`:''}`).join('')}
${children.length?'<h3>PARSED EXPECTATIONS</h3>'+children.map(c=>row(c.id,c.parsing_rationale)).join(''):''}
<h3>TRACE</h3><dl><dt>Stable ID</dt><dd>${esc(n.id)}</dd><dt>Derived from</dt><dd>${esc(n.derived_from||'Direct source record')}</dd>
<dt>Source locator</dt><dd>${esc(n.source_locator)}</dd><dt>Document revision</dt><dd>${esc(src.document_revision_label||src.version)}</dd>
<dt>Policy snapshot</dt><dd>2026-09-28; exact edition applicability unresolved</dd><dt>Review</dt><dd>${esc(n.review_status)}. Review scope belongs to this record; no whole-corpus approval is implied.</dd>
<dt>File SHA-256</dt><dd style="overflow-wrap:anywhere">${esc(src.sha256)}</dd>
<dt>Ontology release</dt><dd>${esc(model.release)}</dd><dt>Research revision</dt><dd>${release.release===model.release&&release.research_commit?`<a href="https://github.com/GarageThermonuclearLaboratories/Minerva/commit/${release.research_commit}" target="_blank" rel="noopener">Inspect matching research state</a>`:'Publication receipt pending for this candidate'}</dd>
<dt>Relationships</dt><dd>${edges.map(e=>esc(e.relation)+' ['+esc(e.status)+']').join('<br>')||'None'}</dd></dl>`;
document.querySelectorAll('#receipt-body [data-node]').forEach(b=>b.onclick=()=>showReceipt(b.dataset.node));
$('#receipt').scrollIntoView({behavior:'smooth',block:'nearest'});
}
function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const row=(id,detail)=>`<button class="row clickable" data-node="${id}"><span><strong>${esc(node(id).label)}</strong><small>${esc(detail)}</small></span><span class="tag ${node(id).status.toLowerCase()}">${node(id).status}</span></button>`;
const gradeLabel=g=>g===0?'Kindergarten':'Grade '+g;
function claimEligible(item){return !!item&&['SOURCE','PARSED'].includes(item.status);}
function activeStandard(n,seen=new Set()){
if(!claimEligible(n)||seen.has(n.id))return false;
if(!n.parent_standard_id)return true;
const link=model.edges.some(e=>e.relation==='PART_OF'&&e.from===n.id&&e.to===n.parent_standard_id&&claimEligible(e));
return link&&activeStandard(node(n.parent_standard_id),new Set([...seen,n.id]));
}
function standardsForGrade(g){
const ids=new Set(model.edges.filter(e=>e.relation==='ASSIGNED_TO_GRADE'&&e.to==='wc:grade:'+g&&claimEligible(e)&&claimEligible(node(e.to))).map(e=>e.from));
return model.nodes.filter(n=>n.type==='Standard'&&ids.has(n.id)&&activeStandard(n));
}
function expectationsForStandard(id){
return model.nodes.filter(n=>n.type==='Expectation'&&n.derived_from===id&&claimEligible(n)&&activeStandard(node(id))&&model.edges.some(e=>e.relation==='DERIVED_FROM'&&e.from===n.id&&e.to===id&&claimEligible(e)));
}
function selectStage(id){
const stage=journey.stages.find(s=>s.id===id);if(!stage)return;
transition=stage.id==='transition';if(!transition)grade=stage.default_grade;
render();
}
function render(){if(!model)return;$('#release-label').textContent=model.release;let [title,intro]=titles[view];$('#title').textContent=title;$('#intro').textContent=intro;document.querySelectorAll('.rail button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let html='';
if(view==='atlas')html=`<div class="section-head"><h2>First mapped region</h2><span>1 parent · 4 subparts · 6 parsed expectations</span></div><div class="cards"><button class="card clickable" data-node="wc:domain:7-rp"><div class="kicker">MATHEMATICS / GRADE 7</div><h3>Ratios & proportional relationships</h3><p>The current entry point into the source-backed graph. Inspect the standard, its four subparts, and six parsed expectations.</p><div class="foot"><span>NY-7.RP.2</span><span>OPEN RECEIPT ↗</span></div></button><div class="panel"><div class="kicker">HOW TO READ THIS ATLAS</div><div class="path"><span>Source</span><i>→</i><span>Standard</span><i>→</i><span>Parsed expectation</span></div><p>Each step carries an epistemic label. The graph currently stops where the evidence stops.</p></div></div><div class="section-head" style="margin-top:38px"><h2>In this region</h2><span>Click for evidence</span></div>${row(standardId,'Original New York wording')}${row('wc:expectation:recognize-proportional','Parsed from “recognize”')}${row('wc:expectation:represent-proportional','Parsed from “represent”')}`;
if(view==='curriculum')html=`<div class="section-head"><h2>Grade → Subject → Domain</h2><span>1 parent standard · 4 subparts</span></div><div class="path"><span>Grade 7</span><i>→</i><span>Mathematics</span><i>→</i><span>Ratios & proportional relationships</span></div>${row(standardId,'NY-7.RP.2 · Recognize and represent proportional relationships between quantities.')}${row('wc:expectation:recognize-proportional','First parsed action')}${row('wc:expectation:represent-proportional','Second parsed action')}<div class="panel" style="margin-top:20px"><div class="kicker">SCOPE NOTE</div><p>Other grades and subjects are not semantically parsed. An empty region here means no data has been ingested, not that New York has no expectation there.</p></div>`;
if(view==='journey')html=`<div class="section-head"><h2>Proportional relationships</h2><span>Grade 7 anchor</span></div><div class="path"><span>Earlier grades<br><small>not mapped</small></span><i>→</i><span>Grade 7 · NY-7.RP.2</span><i>→</i><span>Later grades<br><small>not mapped</small></span></div>${row(standardId,'Source-supported Grade 7 endpoint')}<div class="panel"><div class="kicker">OPEN RESEARCH TASK</div><p>Find and review actual earlier and later standards before asserting a developmental or prerequisite edge. Similar language alone is insufficient.</p></div>`;
if(view==='crossroads')html=`<div class="section-head"><h2>Cross-disciplinary claims</h2><span>0 reviewed · 0 provisional</span></div><div class="panel"><div class="kicker">NO CONNECTIONS PUBLISHED YET</div><p>The Grade 7 mathematics slice contains no second subject to compare. Candidate similarities, rejected equivalences, and review receipts will appear as the source corpus grows.</p></div>`;
if(view==='wildcats'){
const stage=journey.stages.find(s=>transition?s.id==='transition':s.grades.includes(grade));
const standards=standardsForGrade(grade);
html=`<div class="section-head"><h2>${esc(student)} · ${transition?'Graduation / transition':gradeLabel(grade)}</h2><span>Expected learning only</span></div>
<div class="chooser" aria-label="Fictional learner">${model.students.map(s=>`<button class="${student===s.name?'selected':''}" aria-pressed="${student===s.name}" data-student="${esc(s.name)}">${esc(s.name)}</button>`).join('')}</div>
<p class="journey-context">Matthew and Eva share the same reference pathway. These stages organize this view; subjects may use different grade bands or proficiency checkpoints.</p>
<div class="chooser" aria-label="Journey stage">${journey.stages.map(s=>`<button class="${s.id===stage.id?'selected':''}" aria-pressed="${s.id===stage.id}" data-stage="${s.id}">${esc(s.label)}</button>`).join('')}</div>
<div class="panel journey-panel"><h3>${esc(stage.title)}</h3><p>${esc(stage.description)}</p>
${transition?`<h3>Policy evidence still needs review</h3><p>There is no diploma decision or destination prediction for either avatar. The links below are research leads with full review pending.</p><ul>${stage.source_ids.map(id=>{const source=manifest.sources.find(s=>s.id===id);return `<li><a href="${source.url}" target="_blank" rel="noopener">${esc(source.title)}</a> · ${esc(source.acquisition_status)}</li>`;}).join('')}</ul>`:
`<label for="journey-grade">Choose a grade in this stage</label><select id="journey-grade">${stage.grades.map(g=>`<option value="${g}" ${g===grade?'selected':''}>${gradeLabel(g)}</option>`).join('')}</select>
<h3>${standards.length?'Partially mapped: mathematics and ELA':'Not yet mapped'}</h3>
<p>${standards.length?'The current trace contains two standard families: mathematics NY-7.RP.2 with four subparts, and ELA 7R1. Exact edition applicability to the policy snapshot remains unresolved.':esc(journey.missing_data_message)}</p>
${standards.map(n=>row(n.id,n.original_text)+expectationsForStandard(n.id).map(x=>row(x.id,'Parsed expectation · source receipt')).join('')).join('')}`}
</div><p class="journey-context">Policy snapshot: ${journey.policy_snapshot}. This is a reference pathway, not a personal school history. Moving between stages does not establish mastery, cumulative retention, or graduation eligibility.</p>`;
}
if(view==='workbench')html=`<div class="section-head"><h2>Source review checkpoint</h2><span>${esc(model.release)}</span></div><div class="metric-grid">${[[manifest.sources.length,'source records identified'],[manifest.sources.filter(x=>x.acquisition_status==='full-document-acquired').length,'full source documents acquired'],[corpus.families.length,'content areas queued'],['5','source standard records (parent + subparts)'],[model.nodes.filter(n=>n.type==='Expectation').length,'expectations parsed'],['0','reviewed findings']].map(([n,l])=>`<div class="metric"><b>${n}</b><span>${l}</span></div>`).join('')}</div><div class="panel" style="margin-top:18px"><h3>Evidence and coverage</h3><p>Two uploaded mathematics PDFs are archived with hashes. All 184 pages have text extracts; the cover and relevant Grade 7 pages received visual review. Five source standard records and six parsed expectations represent the bounded family. Other source records still rely on search extracts. Human semantic review and full-corpus parsing remain pending.</p><h3>Mathematics policy timeline</h3><p>Prior search excerpts suggested adoption in September 2017, full implementation in September 2022, and aligned Grades 3–8 assessments in spring 2023. These date observations are provisional: their exact supporting excerpts were not preserved, and full-page verification is pending. The uploaded full document says Updated June 2019; exact edition applicability remains under review.</p><a href="https://www.nysed.gov/standards-instruction/mathematics-guidance-resources" target="_blank" rel="noopener">Inspect NYSED guidance ↗</a></div><div class="section-head"><h2>Content-area acquisition queue</h2><span>12 identified; document review pending</span></div>${corpus.families.map(f=>`<div class="panel" style="margin-bottom:10px"><h3>${esc(f.label)}</h3><p>Acquisition: ${esc(f.acquisition)} · Parsing: ${esc(f.parsing)}<br>Normalization: ${esc(f.normalization)} · Relationships: ${esc(f.relationships)}<br>Validation: ${esc(f.validation)} · Human review: ${esc(f.human_review)}</p></div>`).join('')}<p><a href="https://www.nysed.gov/standards-instruction/nys-p-12-learning-standards-content-area" target="_blank" rel="noopener">NYSED content-area inventory ↗</a></p>`;
if(view==='findings')html=`<div class="section-head"><h2>Research state</h2><span>0 published findings</span></div><div class="stack"><div class="panel"><div class="kicker">FINDINGS</div><p>No cross-disciplinary or developmental finding has been established in this bounded slice. This area will link computed results to source IDs, edges, methods, ontology release, and Git revision.</p></div><div class="panel"><div class="kicker">UNRESOLVED QUESTIONS</div>${model.unresolved.map(q=>`<p style="margin-bottom:12px">${esc(q.text)}</p>`).join('')}</div><div class="panel"><div class="kicker">CANONICAL ASSUMPTIONS / REJECTED HYPOTHESES</div><p>Both registers are empty. No local district choice or rejected mapping has yet been evaluated.</p></div></div>`;
if(view==='log')html=`<div class="section-head"><h2>Monday, September 28</h2><span>Initial checkpoint · 0.0.1</span></div><div class="panel"><div class="kicker">SOURCE → STRUCTURE → RECEIPT</div><h2>One standard enters the machine</h2><p>NY-7.RP.2 is represented with its original wording, stable identifier, Grade 7 placement, two parsed expectations, six provenance-bearing edges, and an inspectable receipt.</p><div class="path"><span>7 nodes</span><i>·</i><span>6 edges</span><i>·</i><span>0 findings</span></div><p>First public checkpoint: Site version 1, source commit <code>da6f48d9d9ec725ec8ed33b3f0ac7fbfc515b0ea</code>. The matching Monday research state is archived in <a href="https://github.com/GarageThermonuclearLaboratories/Minerva/commit/647494729893aae73fd764bae9ff2742b260dbd2" target="_blank" rel="noopener">GitHub commit 6474947 ↗</a>. The current Site source commit is recorded in the repository Lab Log. Full PDF page and effective-date verification remain open. No rejected hypothesis has been recorded. The next package expands the primary corpus and verifies its temporal scope.</p></div>`;
if(view==='log')html=`<div class="panel" style="margin-bottom:24px"><div class="kicker">0.0.2 · SOURCE REVIEW AND CORPUS INVENTORY</div><h2>Dates supported; document verification still open</h2><p>Added three source records and a twelve-content-area acquisition queue. Recorded mathematics implementation dates with month and season precision. Corrected the earlier overstatement that the full standard was verified: only its heading is represented from search excerpts.</p><p>PDF downloads failed with HTTP 502. Full source files, page anchors, revisions, and human review remain pending. Graph: 7 nodes, 6 edges, 0 findings.</p><p><a href="https://github.com/GarageThermonuclearLaboratories/Minerva/blob/${release.research_commit||'main'}/docs/source-review.md" target="_blank" rel="noopener">Inspect this review and its evidence ↗</a></p></div>`+html;
if(['atlas','curriculum'].includes(view))html+=`<div class="section-head" style="margin-top:24px"><h2>The four source subparts</h2><span>Verified on page 90</span></div>${['a','b','c','d'].map(k=>row(standardId+k,node(standardId+k).original_text)+model.nodes.filter(n=>n.type==='Expectation'&&n.derived_from===standardId+k).map(n=>row(n.id,'Parsed action · inspect wording and qualifiers')).join('')).join('')}`;
if(view==='journey')html=`<div class="panel"><h2>New York supplies connections</h2><p>The full standards document explicitly labels six arrows involving this family as “Coherence.” They are preserved below as source observations. Their meaning and target standards still need review before they become ontology relationships.</p><p><a href="evidence/math-full/page-90.png" target="_blank" rel="noopener">Inspect the arrows on page 90 ↗</a></p>${review.coherence_observations.map(x=>`<p>${esc(x.source_standard)} → ${esc(x.target_standard)}</p>`).join('')}<p>These are not yet prerequisite claims or computed findings.</p></div>`;
if(view==='log')html=`<div class="panel" style="margin-bottom:24px"><div class="kicker">0.0.3 · ORIGINAL DOCUMENTS ACQUIRED</div><h2>We can now inspect the actual page</h2><p>Two uploaded PDFs are archived and hashed. Page 90 of the full standards verifies NY-7.RP.2 and all four subparts. The supporting crosswalk is visibly marked Draft.</p><p>11 nodes · 14 edges · 2 acquired PDFs · 0 findings. All 184 pages have text extracts; semantic parsing remains a small slice.</p><p><a href="https://github.com/GarageThermonuclearLaboratories/Minerva/blob/${release.research_commit||'main'}/docs/primary-pdf-review.md" target="_blank" rel="noopener">Inspect the PDF review ↗</a></p></div>`+html;
if(view==='log')html='<div class="panel"><h2>Monday semantic trace · candidate</h2><p>All four subparts now have parsed expectations. Source notes and examples are preserved. Grade links record placement, without asserting mastery or an exact attainment date. M7 independent agent audit passed after repairs. Human review and M8 publication remain pending.</p><p>Timeline dates in the historical entries below are now provisional: exact supporting excerpts and section locators were not preserved. Real-browser visual and accessibility QA remains uncompleted.</p></div>'+html;
$('#view').innerHTML=html;document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>showReceipt(b.dataset.node));document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{student=b.dataset.student;render()});document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>selectStage(b.dataset.stage));let gradeSelect=$('#journey-grade');if(gradeSelect)gradeSelect.onchange=e=>{grade=+e.target.value;transition=false;render()};}
document.querySelectorAll('.rail button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo({top:0,behavior:'smooth'})});$('#close-receipt').onclick=()=>$('#receipt-body').innerHTML='<div class="empty-receipt">Select a node to inspect its receipt.</div>';
Promise.all(['data.json','sources.json','corpus-plan.json','source-review.json','release.json','journey.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}))).then(([d,s,c,v,g,j])=>{model=d;manifest=s;corpus=c;review=v;release=g;journey=j;render()}).catch(e=>$('#view').textContent='The ontology slice could not load. Please try again later.');
